/**
 * Turn a MIME type pattern into a case-insensitive regular expression.
 *
 * Every character is escaped so it matches literally, except for `*`, which becomes a
 * greedy wildcard. This lets handlers declare patterns such as `application/vnd.*+json`
 * to match vendor specific JSON types like `application/vnd.api+json`.
 */
const patternToRegExp = (pattern: string): RegExp => {
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, (char) => (char === '*' ? '.*' : `\\${char}`))
  return new RegExp(`^${escaped}$`, 'i')
}

/** Check whether a MIME type matches any of a handler's declared patterns. */
const matchesHandler = (mimeType: string, handler: ResponseBodyHandler): boolean =>
  handler.mimeTypes.some((pattern) => patternToRegExp(pattern).test(mimeType))

/**
 * Find the first plugin response body handler that matches the given MIME type.
 *
 * Plugins without a `responseBody` property are skipped. Matching is case-insensitive and
 * supports wildcard patterns. Returns `undefined` when no handler matches.
 */
export const resolveResponseBodyHandler = (
  mimeType: string,
  plugins: ClientPlugin[],
): ResponseBodyHandler | undefined => {
  for (const plugin of plugins) {
    if (!plugin.responseBody) {
      continue
    }

    const handler = plugin.responseBody.find((candidate) => matchesHandler(mimeType, candidate))
    if (handler) {
      return handler
    }
  }

  return undefined
}
